import{_ as e,o as a,a as d,b as i}from"./app.DKoEZOcr.js";const h=JSON.parse('{"title":"","description":"","frontmatter":{},"headers":[],"relativePath":"guide/operator_practice/typical_operator_cases/simd_operator_impl/matmul_leakyrelu_fusion_operator/intermediate_optimization.md","filePath":"guide/operator_practice/typical_operator_cases/simd_operator_impl/matmul_leakyrelu_fusion_operator/intermediate_optimization.md","outlineHeaders":[{"level":2,"title":"优化手段总览","slug":"优化手段总览","link":"#优化手段总览"},{"level":2,"title":"CV融合：Scenario 1 — CV融合-GM中转","slug":"CV融合：Scenario-1-—-CV融合-GM中转","link":"#CV融合：Scenario-1-—-CV融合-GM中转"},{"level":3,"title":"Matmul优化手段","slug":"Matmul优化手段","link":"#Matmul优化手段"},{"level":3,"title":"Gelu优化手段","slug":"Gelu优化手段","link":"#Gelu优化手段"},{"level":3,"title":"性能数据","slug":"性能数据","link":"#性能数据"}],"lastUpdated":1787050286000}'),r={name:"guide/operator_practice/typical_operator_cases/simd_operator_impl/matmul_leakyrelu_fusion_operator/intermediate_optimization.md"};function l(s,t,o,c,_,p){return a(),d("div",null,[...t[0]||(t[0]=[i(`<div><article class="markdown-body"><h1>中级性能优化<span id="ZH-CN_TOPIC_000000_MATMUL_LEAKYRELU_MID"></span></h1><p>本节在入门功能落地的基础上，介绍Matmul融合算子的中级性能优化方法。</p><blockquote><p><strong>说明</strong>：入门功能落地以Matmul+LeakyRelu融合算子作为讲解样例，而中级和高阶极限打磨以Matmul+Gelu融合算子作为讲解样例。为更好展示VF融合的性能优化手段，本章节以Matmul+Gelu融合算子作为讲解样例。GELU相比LeakyRelu计算逻辑更复杂，能更充分地体现各类优化手段的效果。</p></blockquote><h2 id="优化手段总览">优化手段总览<a class="header-anchor" href="#优化手段总览">​</a></h2><table><thead><tr><th>编号</th><th>优化手段</th><th>说明</th><th>定位</th></tr></thead><tbody><tr><td>1</td><td>L1/L0双缓冲Ping-Pong布局</td><td>Cube核内MTE2搬运和MTE1/Mmad计算并行</td><td>流水线骨架</td></tr><tr><td>2</td><td>大包搬运</td><td>增大搬运粒度，减少搬运次数</td><td>流水线骨架</td></tr><tr><td>3</td><td>细粒度流水同步</td><td>SetFlag/WaitFlag替代PipeBarrier实现更细粒度同步</td><td>流水线骨架</td></tr><tr><td>4</td><td>LoadData3D替代LoadData2D</td><td>减少MTE1指令队列占用</td><td>指令队列优化</td></tr><tr><td>5</td><td>多核并行切分</td><td>按M/N方向切分到多核并行计算</td><td>并行策略</td></tr><tr><td>6</td><td>常量Tiling</td><td>Tiling参数编译期确定，减少运行时Scalar计算开销</td><td>编译期优化</td></tr><tr><td>7</td><td>UnitFlag优化</td><td>Mmad与Fixpipe细粒度流水重叠</td><td>MMAD-FIXPIPE流水重叠</td></tr></tbody></table><h2 id="CV融合：Scenario-1-—-CV融合-GM中转">CV融合：Scenario 1 — CV融合-GM中转<a class="header-anchor" href="#CV融合：Scenario-1-—-CV融合-GM中转">​</a></h2><p>中级性能优化采用CV融合-GM中转方式（A2/A3/Ascend 950PR均支持）。AIC侧通过Fixpipe将L0C计算结果写入GM，AIV侧从GM读取数据到Unified Buffer（UB）后进行GELU计算，再将结果写回GM。</p><p>数据流路径：</p><div class="code-block"><div class="code-header"><span class="lang-label">Text</span><button class="copy-btn" title="复制代码"><svg width="16" height="16" viewBox="0 0 16 16"><path d="M0 6.75C0 5.784.784 5 1.75 5h1.5a.75.75 0 0 1 0 1.5h-1.5a.25.25 0 0 0-.25.25v7.5c0 .138.112.25.25.25h7.5a.25.25 0 0 0 .25-.25v-1.5a.75.75 0 0 1 1.5 0v1.5A1.75 1.75 0 0 1 9.25 16h-7.5A1.75 1.75 0 0 1 0 14.25Z"></path><path d="M5 1.75C5 .784 5.784 0 6.75 0h7.5C15.216 0 16 .784 16 1.75v7.5A1.75 1.75 0 0 1 14.25 11h-7.5A1.75 1.75 0 0 1 5 9.25Zm1.75-.25a.25.25 0 0 0-.25.25v7.5c0 .138.112.25.25.25h7.5a.25.25 0 0 0 .25-.25v-7.5a.25.25 0 0 0-.25-.25Z"></path></svg></button></div><pre class="highlight"><code>GM ──(MTE2)──&gt; L1 ──(MTE1)──&gt; L0A/L0B ──(Cube)──&gt; L0C ──(Fixpipe)──&gt; GM ──(MTE2)──&gt; UB ──(Gelu)──&gt; UB ──(MTE3)──&gt; GM
</code></pre></div><h3 id="Matmul优化手段">Matmul优化手段<a class="header-anchor" href="#Matmul优化手段">​</a></h3><table><thead><tr><th>Case</th><th>优化手段</th><th>说明</th></tr></thead><tbody><tr><td><a href="https://gitcode.com/cann/asc-devkit/blob/master/examples/01_simd_cpp_api/05_best_practices/01_matrix_compute/matmul_high_performance/README.md#case-1-%E5%8D%95%E6%A0%B8tiling%E4%BC%98%E5%8C%96-single_core_tiling">Case 1</a></td><td>单核Tiling优化</td><td>优化base块参数，降低访存计算比</td></tr><tr><td><a href="https://gitcode.com/cann/asc-devkit/blob/master/examples/01_simd_cpp_api/05_best_practices/01_matrix_compute/matmul_high_performance/README.md#case-2-%E5%A4%9A%E6%A0%B8%E5%88%87%E5%88%86-2x12-multi_core_split_2_12">Case 2</a></td><td>多核切分 2x12</td><td>引入多核并行计算，均衡负载分配</td></tr><tr><td><a href="https://gitcode.com/cann/asc-devkit/blob/master/examples/01_simd_cpp_api/05_best_practices/01_matrix_compute/matmul_high_performance/README.md#case-3-%E5%A4%9A%E6%A0%B8%E5%88%87%E5%88%86-4x6-multi_core_split_4_6">Case 3</a></td><td>多核切分 4x6</td><td>优化多核切分策略，地址512B对齐</td></tr><tr><td><a href="https://gitcode.com/cann/asc-devkit/blob/master/examples/01_simd_cpp_api/05_best_practices/01_matrix_compute/matmul_high_performance/README.md#case-4-%E5%A4%9A%E6%A0%B8%E4%BD%BF%E7%94%A8mdl%E6%A8%A1%E6%9D%BF-multi_core_mdl">Case 4</a></td><td>多核使用MDL模板</td><td>启用L1多块缓存，大包搬运</td></tr></tbody></table><h3 id="Gelu优化手段">Gelu优化手段<a class="header-anchor" href="#Gelu优化手段">​</a></h3><table><thead><tr><th>Case</th><th>优化手段</th><th>说明</th></tr></thead><tbody><tr><td><a href="https://gitcode.com/cann/asc-devkit/blob/master/examples/01_simd_cpp_api/05_best_practices/02_reg_compute/gelu_high_performance/README.md#case-1-%E5%90%AF%E7%94%A8regbase-api%E5%92%8Cvf%E8%9E%8D%E5%90%88%E8%83%BD%E5%8A%9B">Case 1</a></td><td>RegBase API + VF融合</td><td>寄存器级计算减少中间Load/Store，利用双发特性提升IPC</td></tr></tbody></table><h3 id="性能数据">性能数据<a class="header-anchor" href="#性能数据">​</a></h3><p>以Ascend 950PR芯片数据为例：</p><ul><li>单独Gelu任务耗时348.868μs，单独Matmul任务耗时2601.311μs</li><li>Scenario 1融合后总耗时2606.91μs，与Matmul单独执行时间基本一致</li></ul><p>这表明采用CV融合方式编写时，AIV的Vector计算时间基本被AIC的Cube计算时间完全覆盖，实现了高效的流水并行。</p><p>详细内容请参见<a href="https://gitcode.com/cann/asc-devkit/blob/master/examples/01_simd_cpp_api/05_best_practices/03_fusion_compute/matmul_gelu_high_performance/README.md">Matmul+Gelu中级性能优化</a>。</p></article></div>`,1)])])}const n=e(r,[["render",l]]);export{h as __pageData,n as default};
